#!/usr/bin/env python3
"""Emit the SIMULATED spatial-cognition vocabulary (sim/*.ttl) from compact specs.

!! SIMULATION. This is NOT Dr. Polys's sc: ontology (16 files, 418 triples, namespace w3id.org/spatial-cognition#; unreadable from here).
!! It is a guess at what such a vocabulary could contain, shaped by what the project's own sources measure, in a namespace that cannot
!! collide with the real one (.invalid). Every concept carries scs:grade "S" and scs:origin "simulated" (or "formalised-from-doc" for the ladder).
Structure mirrors what the fork's loader expects: concepts with x3dNode / x3dField groundings, so real files can replace these 1:1.
"""
from pathlib import Path
SIM = "https://example.invalid/sim/spatial-cognition#"
OUT = Path(__file__).resolve().parent.parent / "sim"; OUT.mkdir(exist_ok=True)
HEAD = f"""# SIMULATED -- not Dr. Polys's sc: ontology. Grade S. Generated by harness/gen_sim.py; do not cite as a source.
@prefix scs: <{SIM}> .
@prefix x3d: <https://www.web3d.org/specifications/X3dOntology4.1#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
"""
# (id, label, comment, nodes, [(node, field)], extras)   extras: tol, check, rung, basis (what real thing it echoes), kind
M = {}
M["perspective"] = [
 ("EyeHeight", "eye height", "Height of the viewer above the walking surface; should be plausible against the avatar and the scene scale.", ["NavigationInfo"], [("NavigationInfo", "avatarSize")], dict(check="semantic rule (proposed): avatarSize[1] vs scene bbox", rung=3, basis="DOC Q1 eye height against avatarSize")),
 ("FieldOfView", "field of view", "Angular extent; X3D spans the smaller viewport dimension, so aspect ratio changes the horizontal view.", ["Viewpoint", "OrthoViewpoint"], [("Viewpoint", "fieldOfView")], dict(check="frame check at 4:3 and 16:9", rung=5, basis="fork PR #5 note, DOC section 2")),
 ("ViewDirection", "view direction", "Where the camera points; orientation rotates the default -Z look vector.", ["Viewpoint"], [("Viewpoint", "orientation")], dict(check="frame check: camera faces content", rung=5, basis="DOC section 2 frame check")),
 ("ViewPosition", "view position", "Camera location in world space; must lie outside solid geometry for a useful first frame.", ["Viewpoint"], [("Viewpoint", "position")], dict(check="frame check", rung=5)),
 ("OrbitPivot", "orbit pivot", "The point examine-mode navigation rotates about; should sit on or near the subject.", ["Viewpoint"], [("Viewpoint", "centerOfRotation")], dict(check="proposed: pivot inside content bbox", rung=3)),
 ("FacingContent", "camera facing content", "The default view shows the content: not blank (<0.05% non-background pixels) and not sparse (<1%).", ["Viewpoint"], [("Viewpoint", "orientation"), ("Viewpoint", "position")], dict(check="analyze_frame blank/sparse", tol=0.0005, rung=5, basis="fork PR #5 frame-check thresholds as quoted in DOC")),
 ("NavigationMode", "navigation mode", "How a person or agent moves: WALK, FLY, EXAMINE, LOOKAT, ANY.", ["NavigationInfo"], [("NavigationInfo", "type")], dict(rung=2)),
 ("HeadlightExposure", "headlight", "Whether a camera-attached light guarantees visibility in unlit scenes.", ["NavigationInfo"], [("NavigationInfo", "headlight")], dict(check="frame check", rung=5)),
 ("VisibilityHorizon", "visibility horizon", "Far distance beyond which geometry is culled; interacts with scale regimes.", ["NavigationInfo"], [("NavigationInfo", "visibilityLimit")], dict(rung=5)),
 ("WalkSpeed", "navigation speed", "Metres per second; a giga-scale scene needs a different speed than a nano-scale one.", ["NavigationInfo"], [("NavigationInfo", "speed")], dict(rung=3)),
 ("ViewpointDescription", "viewpoint description", "Human-readable name so an agent can list and choose views.", ["Viewpoint"], [("Viewpoint", "description")], dict(rung=3)),
]
M["parts_contact"] = [
 ("Part", "part", "A visible volume that is one element of a composite object.", ["Shape"], [], dict(basis="parts_contact.py: Box, Sphere, Cone, Cylinder, point lists")),
 ("Whole", "whole", "A grouping that is more than the sum of its parts: a named composite.", ["Transform", "Group"], [], dict()),
 ("Contact", "contact", "Two parts' world-space bounds touch within a tolerance.", ["Transform"], [("Transform", "translation")], dict(tol=0.05, check="parts_contact.py contact (5% tolerance)", rung=6, basis="step 4 parts_contact.py, tolerance 5%")),
 ("RestsOn", "rests on", "A part rests on another: vertical contact with support from below.", ["Transform"], [("Transform", "translation")], dict(tol=0.05, check="parts_contact.py strict", rung=6, basis="step 4: 'on top of' strict = resting contact; 15 of 34 gpt-4o valid scenes")),
 ("Supports", "supports", "Inverse of RestsOn.", ["Transform"], [], dict(rung=6)),
 ("AttachedTo", "attached to", "Part joined to another; arms to torsos, wings to bodies. No schema states this.", ["Transform", "Group"], [], dict(check="connected components, parts_contact.py", rung=6, basis="step 4: parts touching nothing, human figure 27 of 40 gpt-4o scenes")),
 ("FloatingPart", "floating part", "A part that touches nothing in its composite: a lower-bound defect signal.", ["Shape"], [], dict(check="parts_contact.py components", rung=6, basis="step 4")),
 ("Penetration", "penetration", "One part sinks into another beyond tolerance.", ["Shape"], [], dict(tol=0.05, check="parts_contact.py strict", rung=6, basis="step 4: 24 of 40 sink or leave a gap")),
 ("Gap", "gap", "Measured separation between two parts that should touch.", ["Shape"], [], dict(tol=0.05, rung=6)),
 ("PivotAtHinge", "pivot at hinge", "Animation pivot placed where the part actually hinges, not at the origin.", ["Transform", "SingleAxisHingeJoint"], [("Transform", "center"), ("SingleAxisHingeJoint", "anchorPoint")], dict(check="proposed pivot-vs-bounds check", rung=6, basis="Polys 2024: pump handle rolled instead of swung")),
 ("ConeDirection", "cone direction", "Which way a cone points; the default is +Y, and models rarely set a direction.", ["Cone"], [("Cone", "height")], dict(check="orientation chain from Transform.rotation", rung=6, basis="step 4: 340 of 342 cones point up")),
 ("SupportChain", "support chain", "Every part rests on something that rests on the ground: a stability reading.", ["Transform"], [], dict(rung=6)),
]
M["prepositions"] = [
 ("LeftOf", "left of", "Relation judged on the camera's axes, not the world's.", ["Transform"], [("Transform", "translation")], dict(check="parts_contact.py on camera axes", rung=6, basis="step 4: prompt 4, every valid scene correct")),
 ("RightOf", "right of", "Mirror of LeftOf on the camera's x axis.", ["Transform"], [("Transform", "translation")], dict(rung=6, basis="step 4")),
 ("Above", "above", "Separation along camera up with a gap.", ["Transform"], [("Transform", "translation")], dict(check="strict: separated", rung=6, basis="step 4: prompt 3, 22 strictly separated of 33 valid")),
 ("Below", "below", "Mirror of Above.", ["Transform"], [("Transform", "translation")], dict(rung=6)),
 ("OnTopOf", "on top of", "Above plus resting contact.", ["Transform"], [("Transform", "translation")], dict(check="strict: resting contact", rung=6, basis="step 4: prompt 2")),
 ("InFrontOf", "in front of", "Nearer the camera along the view axis.", ["Transform"], [("Transform", "translation")], dict(rung=6)),
 ("Inside", "inside", "Contained within another volume's bounds.", ["Transform"], [("Transform", "translation")], dict(rung=6)),
 ("Between", "between", "Lies between two parts on a line.", ["Transform"], [("Transform", "translation")], dict(rung=6)),
 ("Beside", "beside", "Adjacent along an axis with a bounded gap.", ["Transform"], [("Transform", "translation")], dict(tol=0.05, rung=6)),
 ("Aligned", "aligned", "Shared edge or centre line within tolerance.", ["Transform"], [("Transform", "translation")], dict(tol=0.05, rung=6)),
 ("Larger", "larger than", "Compares bounding extents.", ["Box", "Sphere"], [("Box", "size"), ("Sphere", "radius")], dict(rung=6)),
]
M["geons"] = [
 ("GeonBlock", "block geon", "A box-like volume as a basic recognisable part.", ["Box"], [("Box", "size")], dict(basis="Biederman geons cited by Polys 2024")),
 ("GeonBall", "ball geon", "A spherical volume.", ["Sphere"], [("Sphere", "radius")], dict()),
 ("GeonPointer", "pointer geon", "A cone: has a direction models rarely set.", ["Cone"], [("Cone", "bottomRadius"), ("Cone", "height")], dict()),
 ("GeonColumn", "column geon", "A cylinder.", ["Cylinder"], [("Cylinder", "radius"), ("Cylinder", "height")], dict()),
 ("GeonSweep", "sweep geon", "A cross-section swept along a spine.", ["Extrusion"], [("Extrusion", "spine"), ("Extrusion", "crossSection")], dict()),
 ("DuckParts", "duck", "Head, body, beak, wings, tail as attached volumes.", ["Group", "Transform"], [], dict(basis="Polys 2024 prompt set: duck", check="parts_contact.py components", rung=6)),
 ("CastleParts", "castle", "Walls, towers, gate, keep.", ["Group", "Transform"], [], dict(basis="Polys 2024: castle; step 4: gemini 3 of 40 with a floating part", rung=6)),
 ("SailboatParts", "sailboat", "Hull, mast, sail, keel.", ["Group", "Transform"], [], dict(basis="Polys 2024: sailboat; step 4: gpt-4o 17 of 38 with a floating part", rung=6)),
 ("HumanFigureParts", "human figure", "Head, torso, arms, legs, attached.", ["Group", "Transform", "HAnimHumanoid"], [], dict(basis="Polys 2024: human figure; step 4: gpt-4o 27 of 40", rung=6)),
 ("PumpParts", "water pump", "Base, barrel, handle, spout; handle pivots.", ["Group", "Transform"], [], dict(basis="Polys 2024 prompt 9", rung=6)),
 ("RecognitionByComponents", "recognition by components", "An object is recognised as a few volumes in relation.", [], [], dict(basis="Biederman 1987 as cited; DOC section 3")),
]
M["scale"] = [
 ("NanoScale", "nano scale", "Features in micrometres to nanometres; float32 loses them far from the origin.", ["Transform"], [("Transform", "scale"), ("Transform", "translation")], dict(check="proposed: |translation| / smallest feature < 2^23", rung=3, basis="IEEE float32 has a 24-bit significand; this is arithmetic, not a measured result")),
 ("HumanScale", "human scale", "Metres; the default unit and the one navigation speed assumes.", ["NavigationInfo"], [("NavigationInfo", "speed")], dict(rung=2)),
 ("PlanetaryScale", "planetary scale", "Kilometres to megametres; needs double precision or geospatial nodes.", ["GeoLocation", "GeoTransform", "GeoCoordinate"], [], dict(rung=3)),
 ("GigaScale", "giga scale", "Whole-structure scale (a shell around a star): relative precision dominates.", ["GeoOrigin", "Transform"], [], dict(basis="project goal: Dyson-shell harness")),
 ("UnitDeclaration", "unit declaration", "UNIT statement declares category, name, conversion factor so scale is explicit.", ["unit"], [("unit", "conversionFactor"), ("unit", "category")], dict(rung=2)),
 ("LevelOfDetail", "level of detail", "Swap representations by distance so giga and nano coexist.", ["LOD", "GeoLOD"], [("LOD", "range"), ("GeoLOD", "range")], dict(rung=5)),
 ("GeospatialPrecision", "geospatial precision", "Coordinates held in doubles with an explicit geoSystem.", ["GeoCoordinate"], [("GeoCoordinate", "geoSystem")], dict(rung=2)),
 ("InstancedRepetition", "instanced repetition", "DEF once, USE many: a million-panel shell stays small.", ["Inline", "Transform"], [], dict(check="use-type check; DEF/USE counts", rung=3, basis="README (28): 2,426 USE lines checked")),
 ("BoundingVolume", "bounding volume", "bboxCenter and bboxSize let a runtime cull at any scale.", ["X3DBoundedObject", "Group"], [("X3DBoundedObject", "bboxSize"), ("X3DBoundedObject", "bboxCenter")], dict(rung=5)),
 ("SceneBudget", "scene budget", "Node and byte counts a runtime can render at a target frame rate.", ["Scene"], [], dict(basis="constellation run: 136,670 bytes for 355 classes", rung=5)),
]
M["heritage"] = [
 ("ClothFrame", "cloth frame", "Shared coordinate frame for the cloth: positions are in cm from the strip edge.", ["Transform"], [("Transform", "translation")], dict(basis="REPORT.md: 4.37 x 1.11 m surface, plate frame")),
 ("PositionStatus", "position status", "measured, estimated, geometric or question: how a feature's position is known.", ["MetadataSet", "MetadataString"], [("MetadataString", "value")], dict(rung=7, basis="REPORT.md: 195 DEF-named features each carry position_status")),
 ("EvidenceRow", "evidence row", "A graded claim: value, uncertainty, primary source, second witness.", ["MetadataSet"], [("MetadataSet", "name")], dict(rung=7, basis="EVIDENCE.md row schema")),
 ("GradeConfirmed", "grade Confirmed", "Peer-reviewed measurement with stated uncertainty, independently reproduced or unrefuted.", ["MetadataString"], [], dict(rung=7, basis="EVIDENCE.md grade definition")),
 ("GradeLikely", "grade Likely", "Peer-reviewed, one group.", ["MetadataString"], [], dict(rung=7, basis="EVIDENCE.md")),
 ("GradeContested", "grade Contested", "Peer-reviewed results on both sides.", ["MetadataString"], [], dict(rung=7, basis="EVIDENCE.md")),
 ("GradeSuspected", "grade Suspected", "Conference, book, preprint, or contradicted without rebuttal.", ["MetadataString"], [], dict(rung=7, basis="EVIDENCE.md")),
 ("GradeQuestion", "grade Question", "The record is silent.", ["MetadataString"], [], dict(rung=7, basis="EVIDENCE.md")),
 ("FeatureHole", "burn hole", "A hole traced from the 2002 photograph with a position and size.", ["Transform", "Shape"], [("Transform", "translation")], dict(basis="REPORT.md: eight big holes 68 +/- 3 cm from ends and middle")),
 ("Synthetic", "synthetic figure", "Not a replica: must be declared in the scene head.", ["WorldInfo"], [("WorldInfo", "info")], dict(rung=7, basis="shroud-print: SYNTHETIC FIGURE - NOT A REPLICA")),
]
M["agency"] = [
 ("Affordance", "affordance", "What a viewer or agent can do with a node: click, enter, follow.", ["TouchSensor", "Anchor", "ProximitySensor"], [("Anchor", "url"), ("TouchSensor", "enabled")], dict(rung=5)),
 ("Triggerable", "triggerable", "A sensor event that starts an animation: isOver, touchTime.", ["TouchSensor", "TimeSensor"], [("TouchSensor", "touchTime"), ("TimeSensor", "startTime")], dict(check="route-aware checks", rung=3)),
 ("ProximityZone", "proximity zone", "A box that fires when the viewer enters.", ["ProximitySensor"], [("ProximitySensor", "size"), ("ProximitySensor", "center")], dict(rung=3)),
 ("Collidable", "collidable", "Geometry the avatar cannot pass; proxy simplifies the test.", ["Collision"], [("Collision", "enabled"), ("Collision", "hasProxy")], dict(rung=5)),
 ("Pickable", "pickable", "Target of a picking sensor.", ["PickableGroup", "LinePickSensor"], [], dict(rung=5)),
 ("RouteWiring", "route wiring", "Event path between typed fields; type mismatches are semantic errors.", ["ROUTE"], [("ROUTE", "fromField"), ("ROUTE", "toField")], dict(check="validate_semantic route checks", rung=3)),
 ("MetadataTag", "metadata tag", "Out-of-band facts attached to a node for agents and ledgers.", ["MetadataSet", "MetadataString", "MetadataFloat"], [("MetadataSet", "hasValue")], dict(rung=7)),
]
M["verification"] = [  # formalised from DOC's ladder; not a simulation of Polys
 ("Rung0Parses", "rung 0: parses", "Well-formed XML or JSON.", [], [], dict(rung=0, kind="rung", check="parser", origin="formalised-from-doc")),
 ("Rung1Typed", "rung 1: typed", "Field types and enumerations.", [], [], dict(rung=1, kind="rung", check="x3d.py constructors, JSON Schema", origin="formalised-from-doc")),
 ("Rung2Valid", "rung 2: valid", "XSD for the declared version.", [], [], dict(rung=2, kind="rung", check="validate_x3d", origin="formalised-from-doc")),
 ("Rung3Coherent", "rung 3: coherent", "DEF/USE, ROUTE types, profile and components.", [], [], dict(rung=3, kind="rung", check="validate_semantic", origin="formalised-from-doc")),
 ("Rung4Lawful", "rung 4: lawful", "Domain rules: what may contain what, units, support.", [], [], dict(rung=4, kind="rung", check="ontology + Schematron/SHACL (not shipped)", origin="formalised-from-doc")),
 ("Rung5Visible", "rung 5: visible", "Something draws, framed sensibly.", [], [], dict(rung=5, kind="rung", check="X_ITE + frame check", origin="formalised-from-doc")),
 ("Rung6Complete", "rung 6: complete", "Shows what was asked.", [], [], dict(rung=6, kind="rung", check="judge model or person; parts_contact.py", origin="formalised-from-doc")),
 ("Rung7Meaningful", "rung 7: meaningful", "True to source, owner and purpose.", [], [], dict(rung=7, kind="rung", check="people + provenance record (x3dprov)", origin="formalised-from-doc")),
]
def lit(s): return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"@en'
for mod, items in M.items():
    out = [HEAD, f"# module: {mod}\n"]
    for cid, label, comment, nodes, fields, x in items:
        origin = x.get("origin", "simulated")
        t = [f"scs:{cid} a scs:{'Rung' if x.get('kind') == 'rung' else 'Concept'} ;", f"  rdfs:label {lit(label)} ;", f"  rdfs:comment {lit(comment)} ;",
             f'  scs:module "{mod}" ;', f'  scs:grade "{"L" if origin != "simulated" else "S"}" ;', f'  scs:origin "{origin}" ;']
        for n in nodes: t.append(f"  scs:x3dNode x3d:{n} ;")
        for n, f in fields: t.append(f"  scs:x3dField [ scs:onNode x3d:{n} ; scs:field \"{f}\" ] ;")
        if "tol" in x: t.append(f'  scs:tolerance "{x["tol"]}"^^xsd:decimal ;')
        if "check" in x: t.append(f"  scs:checkedBy {lit(x['check'])} ;")
        if "rung" in x: t.append(f'  scs:rung {x["rung"]} ;')
        if "basis" in x: t.append(f"  scs:basis {lit(x['basis'])} ;")
        t[-1] = t[-1][:-1] + "."
        out.append("\n".join(t) + "\n")
    (OUT / f"{mod}.ttl").write_text("\n".join(out))
    print(mod, len(items))
print("total", sum(len(v) for v in M.values()))
